INSERT INTO resources (id, author_id, kind, title, summary, body, url, tags, published, created_at, updated_at) VALUES
('res-breath-446', NULL, 'exercise', 'The 4-4-6 breath', 'Sixty seconds that lowers the volume on a stressful moment.', 'Sit or stand. Breathe in through your nose for a count of four. Hold for four. Breathe out through your mouth for six, like you are fogging a mirror. Do it three times. The long exhale is the part that works: it tells your nervous system the danger has passed. Use it before a hard conversation, before you post, or when a notification lands badly.', NULL, '["stress","breathing","divine"]', 1, '2026-10-24T00:00:00Z', '2026-10-24T00:00:00Z'),
('res-sleep-anchor', NULL, 'article', 'One anchor for better sleep', 'Fix the wake time, not the bedtime, and the rest follows.', 'Most sleep advice asks you to go to bed earlier, which is the one thing a busy evening will not allow. Try the other end: pick one wake-up time and keep it seven days a week, including the day after a late night. Within two weeks the body starts getting sleepy at a consistent hour on its own. Pair it with a phone that charges outside the bedroom. Log your hours in Sleep so you can see the pattern settle.', NULL, '["sleep","self"]', 1, '2026-10-24T00:00:00Z', '2026-10-24T00:00:00Z'),
('res-two-line-text', NULL, 'exercise', 'The two-line text', 'A friendship stays alive on messages that cost nothing to answer.', 'Pick one friend you have not spoken to in a month. Send two lines: one that says you thought of them, and one easy question. "Saw a dog that looked exactly like Bruno. How is he?" That is the whole exercise. No catching up, no plans, no apology for the silence. Most friendships do not end, they just go quiet, and a two-line text is enough to restart them.', NULL, '["friendship","connection"]', 1, '2026-10-24T00:00:00Z', '2026-10-24T00:00:00Z'),
('res-flop-is-data', NULL, 'article', 'A setback is data, not a verdict', 'How to read bad news without reading it as a judgement of you.', 'When something you made lands badly, two voices start. One says the work was wrong. The other says you are wrong. Only the first one is useful. Write down three things the result could mean that have nothing to do with your worth: timing, the first line, a bad day on the other side. Then write one thing you will try differently. Then close the numbers. Your Journal has a stress slider for exactly this moment.', NULL, '["self","work","stress"]', 1, '2026-10-24T00:00:00Z', '2026-10-24T00:00:00Z'),
('res-ten-minute-call', NULL, 'exercise', 'The ten-minute call', 'Family gets the first call, and it only needs ten minutes.', 'Set a timer for ten minutes and call a parent, a child or a sibling. Open with one real question about their day, not yours, and then listen until the timer rings. When it rings, say so, and say you will call again at the same time next week. The timer is the point: it makes the call small enough to actually happen, and the repeat is what makes it matter.', NULL, '["family","parent_child"]', 1, '2026-10-24T00:00:00Z', '2026-10-24T00:00:00Z'),
('res-ask-a-mentor', NULL, 'article', 'How to ask a mentor a real question', 'Specific questions get answered. Vague ones get ignored.', 'A real question has three parts: what you tried, what happened, and the one decision you are stuck on. "I did it three times a week for a month, the second one always went worst, should I drop to two or change the second one?" takes thirty seconds to answer and shows respect for their time. Send one of these a week to someone a few steps ahead of you. Log it as a task on the guru floor so the ladder feels it.', NULL, '["guru","learning"]', 1, '2026-10-24T00:00:00Z', '2026-10-24T00:00:00Z');
